import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        final long M = 1000000007L;
        long a = 0;
        long b = 1;
        for (int i = 0; i < n; i++) {
            long c = (a + b) % M;
            a = b;
            b = c;
        }
        System.out.println(a);
    }
}
